import{_ as e}from"./chunks/4f0345d520b09559-20261015000320-h7od16n.CZj_q_D5.js";import{_ as l,o,c as d,a2 as a}from"./chunks/framework.Cms9CC3y.js";const _=JSON.parse('{"title":"按表达式忽略功能说明","description":"","frontmatter":{"title":"按表达式忽略功能说明","date":"2026-10-14T16:03:20.000Z","lastmod":"2026-11-24T18:47:00.000Z"},"headers":[],"relativePath":"guide/1263.md","filePath":"guide/帮助文档/新功能说明/2026/按表达式忽略功能说明.md"}'),r={name:"guide/1263.md"};function i(c,t,n,s,h,u){return o(),d("div",null,[...t[0]||(t[0]=[a('<h1 id="按表达式忽略功能说明" tabindex="-1">按表达式忽略功能说明 <a class="header-anchor" href="#按表达式忽略功能说明" aria-label="Permalink to &quot;按表达式忽略功能说明&quot;">​</a></h1><h1 id="按表达式忽略-―-使用说明" tabindex="-1">按表达式忽略 ― 使用说明 <a class="header-anchor" href="#按表达式忽略-―-使用说明" aria-label="Permalink to &quot;按表达式忽略 ― 使用说明&quot;">​</a></h1><h2 id="功能简介" tabindex="-1">功能简介 <a class="header-anchor" href="#功能简介" aria-label="Permalink to &quot;功能简介&quot;">​</a></h2><p><strong>按表达式忽略</strong>用于在读取仪表数据时，根据您设置的条件判断当前读数是否应被<strong>丢弃</strong>。</p><ul><li>当表达式判断为 <strong>真</strong> 时：本次读数被忽略，不会更新到界面或后续计算。</li><li>当表达式判断为 <strong>假</strong> 时：读数正常参与后续处理。</li></ul><p>常见用途：</p><ul><li>过滤明显异常的读数，例如：​<code>value &lt; -200 OR value &gt; 200</code></li><li>忽略等于特定无效值的读数，例如：​<code>value = 9999</code></li><li>忽略超出合理区间的数据，例如：​<code>value &lt; 0 OR value &gt; 100</code></li></ul><blockquote><p><strong>说明：</strong> 本功能用于<strong>判断是否忽略读数</strong>，不会修改读数本身。若需要对读数进行换算，请使用 <strong>「按表达式转换」</strong> ，两者互不影响。</p></blockquote><hr><h2 id="如何配置" tabindex="-1">如何配置 <a class="header-anchor" href="#如何配置" aria-label="Permalink to &quot;如何配置&quot;">​</a></h2><ol><li>打开 <strong>储罐 / 仪表配置</strong>。</li><li>进入该仪表的 <strong>Modbus 数据地址</strong> 配置页。</li><li>在列表中找到要设置的数据项（如液位、温度等）。</li><li>在 <strong>单位转换</strong> 下拉框中选择 <strong>「按表达式忽略」</strong> 。</li><li>在弹出的对话框中填写表达式，点击 <strong>确定</strong> 保存。</li></ol><p><img src="'+e+'" alt=""></p><hr><h3 id="表达式规则" tabindex="-1">表达式规则 <a class="header-anchor" href="#表达式规则" aria-label="Permalink to &quot;表达式规则&quot;">​</a></h3><ul><li>表达式应写成判断条件，结果为「真」或「假」。</li><li>匹配（结果为真）的读数将被忽略。</li><li>每个数据项可单独配置一条表达式。</li></ul><p>支持的运算符：</p><ul><li><p>比较：​<code>&lt;</code>​、​<code>&gt;</code>​、​<code>&lt;=</code>​、​<code>&gt;=</code>​、​<code>&lt;&gt;</code>​（不等于）、​<code>=</code></p></li><li><p>逻辑运算：​<code>OR</code>​、​<code>&amp;&amp;</code>​、​<code>||</code></p></li><li><p>示例：</p><ul><li>忽略小于0或大于100的读数：​<code>value &lt; 0 OR value &gt; 100</code></li><li>忽略在0～100之间的读数：​<code>value &gt;= 0 AND value &lt;= 100</code></li></ul></li></ul><p>注意事项：</p><ol><li><code>value</code> 是已完成偏移、精度等常规处理之后的读数，不是寄存器原始值。</li><li>本功能仅影响读取，不影响写入。</li><li>请确保条件逻辑符合现场需求：写错条件可能导致正常读数被误忽略，或异常读数未被过滤。</li><li>仅适合简单比较与逻辑组合，不支持复杂函数或文字处理。</li></ol><hr><h2 id="常用示例" tabindex="-1">常用示例 <a class="header-anchor" href="#常用示例" aria-label="Permalink to &quot;常用示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>需求</th><th>表达式</th><th>说明</th></tr></thead><tbody><tr><td>忽略过小或过大的读数</td><td><code>value &lt; -200 OR value &gt; 200</code></td><td>超出 ±200 范围的读数被丢弃</td></tr><tr><td>忽略特定无效值</td><td><code>value = 9999</code></td><td>读数为 9999 时不更新</td></tr><tr><td>忽略负值</td><td><code>value &lt; 0</code></td><td>负值读数被丢弃</td></tr><tr><td>忽略零值</td><td><code>value = 0</code></td><td>读数为 0 时不更新</td></tr><tr><td>忽略合理区间内的读数</td><td><code>value &gt;= 10 AND value &lt;= 90</code></td><td>10～90 之间的读数被丢弃（较少使用）</td></tr></tbody></table><hr><p>检查表达式时注意：</p><ol><li>运算符（​<code>&gt;</code>​、​<code>&lt;</code>等）、比较符号是否正确、括号是否配对；</li><li>可先用 ​<code>value &gt; 0</code> 等简单表达式测试功能。</li></ol><hr><h2 id="修订记录" tabindex="-1">修订记录 <a class="header-anchor" href="#修订记录" aria-label="Permalink to &quot;修订记录&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>1.0</td><td>2026-07-02</td><td>初版</td></tr></tbody></table>',28)])])}const b=l(r,[["render",i]]);export{_ as __pageData,b as default};
